91	    public Outcome submit(UserPrincipal user, Dtos.SubmitReq req, String key) {
92	        if (key == null || key.isBlank()) {
93	            throw Api.error(400, "IDEMPOTENCY_KEY_REQUIRED", "Idempotency-Key header is required");
94	        }
95	        if (key.length() < 8 || key.length() > 64) {
96	            throw Api.error(400, "IDEMPOTENCY_KEY_REQUIRED", "Idempotency-Key must be 8-64 characters");
97	        }
98	        String hash = Util.canonicalSubmit(req);
99	        IdempotencyService.Claim claim = idem.claim(user.id(), key, hash);
100	        if (claim.replay()) {
101	            Map<String, Object> stored = Util.parseMap(claim.replayBody());
102	            return new Outcome(claim.replayStatus(), stored);
103	        }
104	        RedisStockService.Preallocation prealloc = null;
105	        try {
106	            LocalDate ctxDate;
107	            try {
108	                ctxDate = Util.resolveMeal(
109	                        req.deliveryDate() == null || req.deliveryDate().isBlank() ? null : LocalDate.parse(req.deliveryDate()),
110	                        req.mealType(), RequestContext.now()).date();
111	            } catch (ApiException e) {
112	                idem.complete(claim.id(), e.getStatus(), errorBody(e), null);
113	                throw e;
114	            } catch (Exception e) {
115	                ctxDate = RequestContext.today();
116	            }
117	            prealloc = new RedisStockService.Preallocation(ctxDate);
118	            Map<String, Object> data;
119	            try {
120	                data = tx.execute(user.id(), user.email(), req, prealloc, key);
121	            } catch (ConcurrencyFailureException deadlock) {
122	                redisStock.compensate(prealloc);
123	                prealloc = new RedisStockService.Preallocation(ctxDate);
124	                data = tx.execute(user.id(), user.email(), req, prealloc, key);
125	            } catch (DuplicateKeyException dup) {
126	                redisStock.compensate(prealloc);
127	                ApiException mapped = mapDuplicate(dup, user.id(), req);
128	                idem.complete(claim.id(), mapped.getStatus(), errorBody(mapped), null);
129	                throw mapped;
130	            }
131	            idem.complete(claim.id(), 201, Map.of("code", "OK", "message", "Order placed", "data", data),
132	                    ((Number) data.get("orderId")).longValue());
133	            return new Outcome(201, Map.of("code", "OK", "message", "Order placed", "data", data));
134	        } catch (ApiException e) {
135	            if (prealloc != null) redisStock.compensate(prealloc);
136	            idem.complete(claim.id(), e.getStatus(), errorBody(e), null);
137	            throw e;
138	        } catch (RuntimeException e) {
139	            if (prealloc != null) redisStock.compensate(prealloc);
140	            idem.fail(claim.id());
141	            throw e;
142	        }
143	    }
