265	    @Transactional
266	    public Map<String, Object> cancel(UserPrincipal user, long orderId, String reason) {
267	        List<Map<String, Object>> rows = jdbc.queryForList("SELECT * FROM orders WHERE id=?", orderId);
268	        if (rows.isEmpty()) throw Api.error(404, "ORDER_NOT_FOUND", "Order not found");
269	        Map<String, Object> o = rows.get(0);
270	        long owner = ((Number) o.get("user_id")).longValue();
271	        if (!user.isAdmin() && owner != user.id()) throw Api.error(404, "ORDER_NOT_FOUND", "Order not found");
272	        if (reason != null && reason.length() > 200) {
273	            throw Api.error(400, "VALIDATION_REASON_REQUIRED", "Reason must be at most 200 characters");
274	        }
275	        if (user.isAdmin() && (reason == null || reason.isBlank())) {
276	            throw Api.error(400, "VALIDATION_REASON_REQUIRED", "A reason is required for admin operations");
277	        }
278	        String status = String.valueOf(o.get("status"));
279	        int n = jdbc.update("UPDATE orders SET status='Cancelled', cancelled_at=NOW(3), cancel_reason=? "
280	                + "WHERE id=? AND status='Pending'", reason, orderId);
281	        if (n == 0) {
282	            if ("Cancelled".equals(status) || "Confirmed".equals(status) || "Completed".equals(status)) {
283	                throw Api.error(409, "ORDER_STATE_INVALID", "Only pending orders can be cancelled");
284	            }
285	            throw Api.error(409, "ORDER_STATE_INVALID", "Order state changed, please retry");
286	        }
287	        LocalDate date = ((java.sql.Date) o.get("delivery_date")).toLocalDate();
288	        for (Map<String, Object> r : aggregatedItems(orderId)) {
289	            long dishId = ((Number) r.get("dish_id")).longValue();
290	            int qty = Util.intVal(r.get("qty"));
291	            inventory.release(orderId, dishId, date, qty, user.email(), reason == null ? "CANCELLED" : reason);
292	            redisStock.sync(date, dishId, inventory.available(dishId, date));
293	        }
294	        if (user.isAdmin()) {
295	            audit.log("ORDER_CANCEL", "ORDER", String.valueOf(orderId),
296	                    Map.of("status", status), Map.of("status", "Cancelled"), reason);
297	        }
298	        Map<String, Object> data = new LinkedHashMap<>();
299	        data.put("orderId", orderId);
300	        data.put("status", "Cancelled");
301	        data.put("cancelledAt", Util.iso(jdbc.queryForObject("SELECT cancelled_at FROM orders WHERE id=?", Timestamp.class, orderId)));
302	        return data;
303	    }
