309	    /** Timeout release path: CAS status + release reserved stock exactly once. */
310	    @Transactional
311	    public boolean timeoutCancel(long orderId) {
312	        List<Map<String, Object>> rows = jdbc.queryForList("SELECT * FROM orders WHERE id=? AND status='Pending'", orderId);
313	        if (rows.isEmpty()) return false;
314	        Map<String, Object> o = rows.get(0);
315	        int n = jdbc.update("UPDATE orders SET status='Cancelled', cancelled_at=NOW(3), cancel_reason='TIMEOUT' "
316	                + "WHERE id=? AND status='Pending'", orderId);
317	        if (n == 0) return false;
318	        LocalDate date = ((java.sql.Date) o.get("delivery_date")).toLocalDate();
319	        for (Map<String, Object> r : aggregatedItems(orderId)) {
320	            long dishId = ((Number) r.get("dish_id")).longValue();
321	            inventory.release(orderId, dishId, date, Util.intVal(r.get("qty")), "SYSTEM", "TIMEOUT");
322	            redisStock.sync(date, dishId, inventory.available(dishId, date));
323	        }
324	        return true;
325	    }
