327	    @Transactional
328	    public void adminPatchStatus(long orderId, String toStatus, String reason) {
329	        if (reason == null || reason.isBlank() || reason.length() > 200) {
330	            throw Api.error(400, "VALIDATION_REASON_REQUIRED", "A reason of 1-200 characters is required");
331	        }
332	        if (!List.of("Confirmed", "Completed", "Cancelled").contains(toStatus)) {
333	            throw Api.error(400, "VALIDATION_INVALID", "Invalid target status");
334	        }
335	        List<Map<String, Object>> rows = jdbc.queryForList("SELECT * FROM orders WHERE id=?", orderId);
336	        if (rows.isEmpty()) throw Api.error(404, "ORDER_NOT_FOUND", "Order not found");
337	        Map<String, Object> o = rows.get(0);
338	        String from = String.valueOf(o.get("status"));
339	        if (!OrderStateMachine.canTransition(from, toStatus)) {
340	            throw Api.error(409, "ORDER_STATE_INVALID", "Illegal order state transition " + from + " -> " + toStatus);
341	        }
342	        int n = jdbc.update("UPDATE orders SET status=?, cancelled_at=CASE WHEN ?='Cancelled' THEN NOW(3) ELSE cancelled_at END, "
343	                        + "cancel_reason=CASE WHEN ?='Cancelled' THEN ? ELSE cancel_reason END WHERE id=? AND status=?",
344	                toStatus, toStatus, toStatus, reason, orderId, from);
345	        if (n == 0) throw Api.error(409, "ORDER_STATE_INVALID", "Order state changed, please retry");
346	        LocalDate date = ((java.sql.Date) o.get("delivery_date")).toLocalDate();
347	        if ("Confirmed".equals(toStatus)) {
348	            for (Map<String, Object> r : aggregatedItems(orderId)) {
349	                long dishId = ((Number) r.get("dish_id")).longValue();
350	                inventory.confirm(orderId, dishId, date, Util.intVal(r.get("qty")), "admin", reason);
351	            }
352	        } else if ("Cancelled".equals(toStatus)) {
353	            for (Map<String, Object> r : aggregatedItems(orderId)) {
354	                long dishId = ((Number) r.get("dish_id")).longValue();
355	                inventory.release(orderId, dishId, date, Util.intVal(r.get("qty")), "admin", reason);
356	                redisStock.sync(date, dishId, inventory.available(dishId, date));
357	            }
358	        }
359	        audit.log("ORDER_STATUS", "ORDER", String.valueOf(orderId),
360	                Map.of("status", from), Map.of("status", toStatus), reason);
361	    }
