45	    public Calc validateAndPrice(long userId, List<Dtos.ItemReq> items, String deliveryDate, String mealType) {
46	        if (items == null || items.isEmpty()) throw Api.error(400, "VALIDATION_QUANTITY", "At least one item is required");
47	        LocalDate reqDate = deliveryDate == null || deliveryDate.isBlank() ? null
48	                : Util.parseDate(deliveryDate, "VALIDATION_INVALID");
49	        Util.Effective eff = Util.resolveMeal(reqDate, mealType, RequestContext.now());
50	        int itemCount = 0;
51	        List<Line> lines = new ArrayList<>();
52	        for (Dtos.ItemReq item : items) {
53	            if (item == null || item.dishId() == null) throw Api.error(400, "VALIDATION_QUANTITY", "dishId is required");
54	            int qty = item.qty() == null ? 0 : item.qty();
55	            if (qty < 1 || qty > 5) throw Api.error(400, "VALIDATION_QUANTITY", "qty must be between 1 and 5");
56	            itemCount += qty;
57	            if (itemCount > 5) throw Api.error(400, "ORDER_LIMIT_EXCEEDED", "At most 5 portions per order");
58	            List<Map<String, Object>> dishes = jdbc.queryForList(
59	                    "SELECT d.id,d.name,d.price_cents FROM daily_menu m JOIN dishes d ON d.id=m.dish_id "
60	                            + "WHERE d.id=? AND m.serve_date=? AND m.publish_status='PUBLISHED' AND d.status='ON_SHELF'",
61	                    item.dishId(), eff.date());
62	            if (dishes.isEmpty()) {
63	                throw Api.error(409, "ORDER_MEAL_UNAVAILABLE", "Dish " + item.dishId() + " is not available for this meal");
64	            }
65	            Map<String, Object> dish = dishes.get(0);
66	            long unit = Util.cents(dish.get("price_cents"));
67	            List<Map<String, Object>> selectedOptions = new ArrayList<>();
68	            List<Long> optionIds = item.optionIds() == null ? List.of() : item.optionIds();
69	            if (optionIds.size() != optionIds.stream().distinct().count()) {
70	                throw Api.error(400, "VALIDATION_OPTION_INVALID", "Duplicate optionId");
71	            }
72	            List<Map<String, Object>> groups = jdbc.queryForList(
73	                    "SELECT id,name,required,min_select,max_select FROM dish_option_groups WHERE dish_id=? ORDER BY sort_order,id",
74	                    item.dishId());
75	            Map<Long, Map<Long, Object>> optionsByGroup = new LinkedHashMap<>();
76	            for (Map<String, Object> g : groups) {
77	                optionsByGroup.put(((Number) g.get("id")).longValue(), new LinkedHashMap<>());
78	            }
79	            for (Long oid : optionIds) {
80	                List<Map<String, Object>> opts = jdbc.queryForList(
81	                        "SELECT o.id,o.group_id,o.name,o.price_delta_cents FROM dish_options o "
82	                                + "JOIN dish_option_groups g ON g.id=o.group_id WHERE o.id=? AND g.dish_id=?",
83	                        oid, item.dishId());
84	                if (opts.isEmpty()) throw Api.error(400, "VALIDATION_OPTION_INVALID", "Option " + oid + " does not belong to this dish");
85	                Map<String, Object> o = opts.get(0);
86	                long gid = ((Number) o.get("group_id")).longValue();
87	                Map<String, Object> g = groups.stream()
88	                        .filter(x -> ((Number) x.get("id")).longValue() == gid).findFirst().orElseThrow();
89	                Map<Long, Object> inGroup = optionsByGroup.get(gid);
90	                if (inGroup.size() >= Util.intVal(g.get("max_select"))) {
91	                    throw Api.error(400, "VALIDATION_OPTION_INVALID", "Too many options selected for group " + g.get("name"));
92	                }
93	                inGroup.put(oid, o);
94	                unit += Util.cents(o.get("price_delta_cents"));
95	                Map<String, Object> om = new LinkedHashMap<>();
96	                om.put("name", o.get("name"));
97	                om.put("priceDeltaCents", Util.cents(o.get("price_delta_cents")));
98	                selectedOptions.add(om);
99	            }
100	            for (Map<String, Object> g : groups) {
101	                long gid = ((Number) g.get("id")).longValue();
102	                int min = Util.intVal(g.get("min_select"));
103	                if (Util.intVal(g.get("required")) == 1) min = Math.max(min, 1);
104	                int chosen = optionsByGroup.get(gid).size();
105	                if (chosen < min) {
106	                    throw Api.error(400, "VALIDATION_OPTION_REQUIRED", "Group '" + g.get("name") + "' requires a selection");
107	                }
108	            }
109	            lines.add(new Line(((Number) dish.get("id")).longValue(), String.valueOf(dish.get("name")),
110	                    qty, unit, unit * qty, selectedOptions));
111	        }
112	        long total = lines.stream().mapToLong(Line::subtotal).sum();
113	        boolean budgetExceeded = false;
114	        List<Map<String, Object>> prefs = jdbc.queryForList(
115	                "SELECT budget_max_cents FROM user_preferences WHERE user_id=?", userId);
116	        if (!prefs.isEmpty() && prefs.get(0).get("budget_max_cents") != null) {
117	            budgetExceeded = total > Util.cents(prefs.get(0).get("budget_max_cents"));
118	        }
119	        return new Calc(lines, total, itemCount, eff, budgetExceeded);
120	    }
121	
122	    /** T1: single business transaction, DB writes only. */
123	    @Transactional(isolation = Isolation.READ_COMMITTED, rollbackFor = Exception.class)
124	    public Map<String, Object> execute(long userId, String email, Dtos.SubmitReq req, RedisStockService.Preallocation ctx, String idemKey) {
125	        String address = req.address() == null ? "" : req.address().trim();
126	        if (address.isEmpty() || address.length() > 200) {
127	            throw Api.error(400, "VALIDATION_ADDRESS_LENGTH", "Address is required and must be at most 200 characters");
128	        }
129	        Calc calc = validateAndPrice(userId, req.items(), req.deliveryDate(), req.mealType());
130	        Util.Effective eff = calc.effective();
131	
132	        List<Map<String, Object>> existing = jdbc.queryForList(
133	                "SELECT id,order_no FROM orders WHERE user_id=? AND delivery_date=? AND meal_type=? "
134	                        + "AND status IN ('Pending','Confirmed') LIMIT 1", userId, eff.date(), eff.meal());
135	        if (!existing.isEmpty()) {
136	            Map<String, Object> data = new LinkedHashMap<>();
137	            data.put("existingOrderId", existing.get(0).get("id"));
138	            data.put("existingOrderNo", existing.get(0).get("order_no"));
139	            throw Api.error(409, "ORDER_DUPLICATE", "An active order already exists for this meal", data);
140	        }
141	
142	        // Aggregate quantities per dish and reserve in ascending dish_id order (deadlock reduction).
143	        Map<Long, Integer> demand = new TreeMap<>();
144	        for (Line l : calc.lines()) demand.merge(l.dishId(), l.qty(), Integer::sum);
145	
146	        Map<Long, int[]> reserved = new LinkedHashMap<>();
147	        for (Map.Entry<Long, Integer> e : demand.entrySet()) {
148	            long dishId = e.getKey();
149	            LocalDate date = eff.date();
150	            String mode = inventory.mode(dishId, date);
151	            int available = inventory.available(dishId, date);
152	            if ("REDIS_PREALLOC".equals(mode)) {
153	                redisStock.prealloc(ctx, dishId, date, e.getValue(), available);
154	            }
155	            int[] delta = inventory.reserve(dishId, date, e.getValue());
156	            reserved.put(dishId, delta);
157	        }
158	
159	        // Insert order + items snapshot.
160	        String tempNo = "T" + java.util.UUID.randomUUID().toString().replace("-", "").substring(0, 20);
161	        Map<String, Object> snapshot = new LinkedHashMap<>();
162	        List<Map<String, Object>> snapItems = new ArrayList<>();
163	        for (Line l : calc.lines()) {
164	            Map<String, Object> sm = new LinkedHashMap<>();
165	            sm.put("dishId", l.dishId());
166	            sm.put("dishName", l.dishName());
167	            sm.put("unitPriceCents", l.unitPrice());
168	            sm.put("options", l.options());
169	            sm.put("qty", l.qty());
170	            sm.put("subtotalCents", l.subtotal());
171	            snapItems.add(sm);
172	        }
173	        snapshot.put("items", snapItems);
174	        snapshot.put("totalCents", calc.totalCents());
175	        snapshot.put("address", address);
176	        snapshot.put("deliveryDate", eff.date().toString());
177	        snapshot.put("mealType", eff.meal());
178	        snapshot.put("createdAt", RequestContext.now().toOffsetDateTime().toString());
179	
180	        KeyHolder keyHolder = new GeneratedKeyHolder();
181	        jdbc.update(con -> {
182	            PreparedStatement ps = con.prepareStatement(
183	                    "INSERT INTO orders(order_no,user_id,status,delivery_date,meal_type,address,total_cents,item_count,"
184	                            + "budget_exceeded,idempotency_key,snapshot_json) VALUES (?,?,'Pending',?,?,?,?,?,?,?,?)",
185	                    Statement.RETURN_GENERATED_KEYS);
186	            ps.setString(1, tempNo);
187	            ps.setLong(2, userId);
188	            ps.setDate(3, java.sql.Date.valueOf(eff.date()));
189	            ps.setString(4, eff.meal());
190	            ps.setString(5, address);
191	            ps.setLong(6, calc.totalCents());
192	            ps.setInt(7, calc.itemCount());
193	            ps.setInt(8, calc.budgetExceeded() ? 1 : 0);
194	            ps.setString(9, idemKey);
195	            ps.setString(10, Util.json(snapshot));
196	            return ps;
197	        }, keyHolder);
198	        long orderId = keyHolder.getKey().longValue();
199	        String orderNo = "WB" + eff.date().toString().replace("-", "") + "-" + String.format("%04d", orderId % 10000);
200	        jdbc.update("UPDATE orders SET order_no=? WHERE id=?", orderNo, orderId);
201	
202	        for (Line l : calc.lines()) {
203	            jdbc.update("INSERT INTO order_items(order_id,dish_id,dish_name,unit_price_cents,options_json,qty,subtotal_cents) "
204	                            + "VALUES (?,?,?,?,?,?,?)",
205	                    orderId, l.dishId(), l.dishName(), l.unitPrice(), Util.json(l.options()), l.qty(), l.subtotal());
206	        }
207	        for (Map.Entry<Long, int[]> e : reserved.entrySet()) {
208	            int[] delta = e.getValue();
209	            inventory.reserveLedger(orderId, e.getKey(), eff.date(), demand.get(e.getKey()), delta[0], delta[1], email);
210	        }
211	
212	        jdbc.update("INSERT INTO addresses(user_id,address) VALUES (?,?) ON DUPLICATE KEY UPDATE usage_count=usage_count+1, last_used_at=NOW(3)",
213	                userId, address);
214	
215	        Map<String, Object> data = new LinkedHashMap<>();
216	        data.put("orderId", orderId);
217	        data.put("orderNo", orderNo);
218	        data.put("status", "Pending");
219	        data.put("deliveryDate", eff.date().toString());
220	        data.put("mealType", eff.meal());
221	        data.put("address", address);
222	        data.put("totalCents", calc.totalCents());
223	        data.put("itemCount", calc.itemCount());
224	        data.put("autoSwitched", eff.autoSwitched());
225	        data.put("estimatedDelivery", eff.meal() + " on " + eff.date());
226	        return data;
227	    }
228	
229	}

1	package com.webox.order;
2	
3	import com.webox.common.Api;
4	import com.webox.common.Util;
5	import org.springframework.dao.DuplicateKeyException;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.stereotype.Service;
8	import org.springframework.transaction.annotation.Propagation;
9	import org.springframework.transaction.annotation.Transactional;
10	
11	import java.sql.Timestamp;
12	import java.time.LocalDateTime;
13	import java.util.Map;
14	
15	@Service
16	public class IdempotencyService {
17	    private final JdbcTemplate jdbc;
18	
19	    public IdempotencyService(JdbcTemplate jdbc) {
20	        this.jdbc = jdbc;
21	    }
22	
23	    public record Claim(long id, Integer replayStatus, String replayBody) {
24	        public boolean replay() { return replayStatus != null; }
25	    }
26	
27	    /** T0: claims the key in an independent autocommit transaction. */
28	    public Claim claim(long userId, String key, String hash) {
29	        try {
30	            jdbc.update("INSERT INTO idempotency_records(user_id,idem_key,request_hash,status,expires_at) "
31	                            + "VALUES (?,?,?,'IN_PROGRESS',?)",
32	                    userId, key, hash, LocalDateTime.now().plusHours(24));
33	            Long id = jdbc.queryForObject(
34	                    "SELECT id FROM idempotency_records WHERE user_id=? AND idem_key=?", Long.class, userId, key);
35	            return new Claim(id, null, null);
36	        } catch (DuplicateKeyException ignored) {
37	            // fall through to the replay / conflict path
38	        }
39	        for (int attempt = 0; attempt < 11; attempt++) {
40	            Map<String, Object> row = jdbc.queryForMap(
41	                    "SELECT id,request_hash,status,response_status,response_body,updated_at FROM idempotency_records "
42	                            + "WHERE user_id=? AND idem_key=?", userId, key);
43	            String existingHash = String.valueOf(row.get("request_hash"));
44	            if (!existingHash.equals(hash)) {
45	                throw Api.error(409, "IDEMPOTENCY_CONFLICT", "Idempotency-Key was used with a different request body");
46	            }
47	            long id = ((Number) row.get("id")).longValue();
48	            String status = String.valueOf(row.get("status"));
49	            if ("COMPLETED".equals(status)) {
50	                return new Claim(id, ((Number) row.get("response_status")).intValue(),
51	                        row.get("response_body") == null ? null : String.valueOf(row.get("response_body")));
52	            }
53	            if ("FAILED".equals(status)) {
54	                int n = jdbc.update("UPDATE idempotency_records SET status='IN_PROGRESS' WHERE id=? AND status='FAILED'", id);
55	                if (n == 1) return new Claim(id, null, null);
56	                continue;
57	            }
58	            Object updatedRaw = row.get("updated_at");
59	            LocalDateTime updated = updatedRaw instanceof LocalDateTime ldt ? ldt
60	                    : updatedRaw instanceof Timestamp ts ? ts.toLocalDateTime() : null;
61	            if (updated != null && updated.isBefore(LocalDateTime.now().minusSeconds(30))) {
62	                int n = jdbc.update("UPDATE idempotency_records SET status='IN_PROGRESS' "
63	                        + "WHERE id=? AND status='IN_PROGRESS' AND updated_at=?", id, updated);
64	                if (n == 1) return new Claim(id, null, null);
65	                continue;
66	            }
67	            try {
68	                Thread.sleep(200);
69	            } catch (InterruptedException e) {
70	                Thread.currentThread().interrupt();
71	                break;
72	            }
73	        }
74	        throw Api.error(409, "IDEMPOTENCY_CONFLICT", "A request with this Idempotency-Key is still in progress");
75	    }
76	
77	    /** T2: independent transaction storing the outcome snapshot (including business 4xx). */
78	    @Transactional(propagation = Propagation.REQUIRES_NEW)
79	    public void complete(long id, int status, Map<String, Object> body, Long orderId) {
80	        jdbc.update("UPDATE idempotency_records SET status='COMPLETED', response_status=?, response_body=?, order_id=? WHERE id=?",
81	                status, Util.json(body), orderId, id);
82	    }
83	
84	    @Transactional(propagation = Propagation.REQUIRES_NEW)
85	    public void fail(long id) {
86	        jdbc.update("UPDATE idempotency_records SET status='FAILED', response_status=500 WHERE id=? AND status='IN_PROGRESS'", id);
87	    }
88	
89	    public int cleanup() {
90	        return jdbc.update("DELETE FROM idempotency_records WHERE expires_at < NOW(3) LIMIT 1000");
91	    }
92	}

1	package com.webox.inventory;
2	
3	import com.webox.common.Api;
4	import com.webox.realtime.SseHub;
5	import org.springframework.jdbc.core.JdbcTemplate;
6	import org.springframework.stereotype.Service;
7	import org.springframework.transaction.support.TransactionSynchronization;
8	import org.springframework.transaction.support.TransactionSynchronizationManager;
9	
10	import java.time.LocalDate;
11	import java.util.LinkedHashMap;
12	import java.util.List;
13	import java.util.Map;
14	
15	@Service
16	public class InventoryService {
17	    private final JdbcTemplate jdbc;
18	    private final SseHub sseHub;
19	
20	    public InventoryService(JdbcTemplate jdbc, SseHub sseHub) {
21	        this.jdbc = jdbc;
22	        this.sseHub = sseHub;
23	    }
24	
25	    public int available(long dishId, LocalDate date) {
26	        List<Map<String, Object>> rows = jdbc.queryForList(
27	                "SELECT total_qty-reserved_qty-sold_qty AS available FROM dish_daily_stock WHERE dish_id=? AND serve_date=?",
28	                dishId, date);
29	        if (rows.isEmpty()) return 0;
30	        return Math.max(0, ((Number) rows.get(0).get("available")).intValue());
31	    }
32	
33	    /** Atomic conditional reservation. Returns {before, after}. */
34	    public int[] reserve(long dishId, LocalDate date, int qty) {
35	        int n = jdbc.update("UPDATE dish_daily_stock SET reserved_qty=reserved_qty+?, version=version+1 "
36	                        + "WHERE dish_id=? AND serve_date=? AND total_qty-reserved_qty-sold_qty>=?",
37	                qty, dishId, date, qty);
38	        if (n == 0) {
39	            int avail = available(dishId, date);
40	            Map<String, Object> detail = new LinkedHashMap<>();
41	            detail.put("dishId", dishId);
42	            detail.put("requested", qty);
43	            detail.put("available", avail);
44	            Map<String, Object> data = new LinkedHashMap<>();
45	            data.put("details", List.of(detail));
46	            throw Api.error(409, "STOCK_INSUFFICIENT", "Some dishes are sold out or insufficient", data);
47	        }
48	        int after = available(dishId, date);
49	        publish(dishId, after);
50	        return new int[]{after + qty, after};
51	    }
52	
53	    public String mode(long dishId, LocalDate date) {
54	        List<String> m = jdbc.queryForList(
55	                "SELECT inventory_mode FROM dish_daily_stock WHERE dish_id=? AND serve_date=?", String.class, dishId, date);
56	        return m.isEmpty() ? "DB_ATOMIC" : m.get(0);
57	    }
58	
59	    /** Release reserved stock exactly once, guarded by ledger business key. */
60	    public void release(long orderId, long dishId, LocalDate date, int qty, String operator, String reason) {
61	        String businessKey = "ORD:" + orderId + ":D:" + dishId + ":RELEASE";
62	        Map<String, Object> row = lockStock(dishId, date, qty);
63	        int before = ((Number) row.get("available")).intValue();
64	        int inserted = jdbc.update("INSERT IGNORE INTO inventory_ledger"
65	                        + "(order_id,dish_id,serve_date,entry_type,qty,before_available,after_available,business_key,operator,reason) "
66	                        + "VALUES (?,?,?,'RELEASE',?,?,?,?,?,?)",
67	                orderId, dishId, date, qty, before, before + qty, businessKey, operator, reason);
68	        if (inserted == 0) return; // already released
69	        int n = jdbc.update("UPDATE dish_daily_stock SET reserved_qty=reserved_qty-?, version=version+1 "
70	                + "WHERE dish_id=? AND serve_date=? AND reserved_qty>=?", qty, dishId, date, qty);
71	        if (n == 0) throw Api.error(409, "ORDER_STATE_INVALID", "Reserved stock is inconsistent");
72	        publish(dishId, before + qty);
73	    }
74	
75	    /** Move reserved -> sold exactly once. */
76	    public void confirm(long orderId, long dishId, LocalDate date, int qty, String operator, String reason) {
77	        String businessKey = "ORD:" + orderId + ":D:" + dishId + ":CONFIRM";
78	        Map<String, Object> row = lockStock(dishId, date, qty);
79	        int before = ((Number) row.get("available")).intValue();
80	        int inserted = jdbc.update("INSERT IGNORE INTO inventory_ledger"
81	                        + "(order_id,dish_id,serve_date,entry_type,qty,before_available,after_available,business_key,operator,reason) "
82	                        + "VALUES (?,?,?,'CONFIRM',?,?,?,?,?,?)",
83	                orderId, dishId, date, qty, before, before, businessKey, operator, reason);
84	        if (inserted == 0) return;
85	        int n = jdbc.update("UPDATE dish_daily_stock SET reserved_qty=reserved_qty-?, sold_qty=sold_qty+?, version=version+1 "
86	                + "WHERE dish_id=? AND serve_date=? AND reserved_qty>=?", qty, qty, dishId, date, qty);
87	        if (n == 0) throw Api.error(409, "ORDER_STATE_INVALID", "Reserved stock is inconsistent");
88	    }
89	
90	    public void reserveLedger(long orderId, long dishId, LocalDate date, int qty, int before, int after, String operator) {
91	        jdbc.update("INSERT IGNORE INTO inventory_ledger"
92	                        + "(order_id,dish_id,serve_date,entry_type,qty,before_available,after_available,business_key,operator,reason) "
93	                        + "VALUES (?,?,?,'RESERVE',?,?,?,?,?,?)",
94	                orderId, dishId, date, qty, before, after, "ORD:" + orderId + ":D:" + dishId + ":RESERVE", operator, null);
95	    }
96	
97	    public void adjust(long dishId, LocalDate date, int delta, String operator, String reason) {
98	        int n = jdbc.update("UPDATE dish_daily_stock SET total_qty=total_qty+?, version=version+1 "
99	                + "WHERE dish_id=? AND serve_date=? AND total_qty+?>=reserved_qty+sold_qty", delta, dishId, date, delta);
100	        if (n == 0) throw Api.error(409, "STOCK_INSUFFICIENT", "Adjusted total cannot be lower than reserved + sold");
101	        int after = available(dishId, date);
102	        int before = after - delta;
103	        jdbc.update("INSERT INTO inventory_ledger"
104	                        + "(dish_id,serve_date,entry_type,qty,before_available,after_available,business_key,operator,reason) "
105	                        + "VALUES (?,?,'ADJUST',?,?,?,?,?,?)",
106	                dishId, date, Math.abs(delta), before, after,
107	                "ADJ:" + java.util.UUID.randomUUID(), operator, reason);
108	        publish(dishId, after);
109	    }
110	
111	    private Map<String, Object> lockStock(long dishId, LocalDate date, int qty) {
112	        List<Map<String, Object>> rows = jdbc.queryForList(
113	                "SELECT total_qty,reserved_qty,sold_qty,total_qty-reserved_qty-sold_qty AS available "
114	                        + "FROM dish_daily_stock WHERE dish_id=? AND serve_date=? FOR UPDATE", dishId, date);
115	        if (rows.isEmpty()) throw Api.error(409, "STOCK_INSUFFICIENT", "Stock row missing for dish " + dishId);
116	        if (((Number) rows.get(0).get("reserved_qty")).intValue() < qty) {
117	            throw Api.error(409, "ORDER_STATE_INVALID", "Reserved stock is inconsistent");
118	        }
119	        return rows.get(0);
120	    }
121	
122	    private void publish(long dishId, int available) {
123	        if (TransactionSynchronizationManager.isSynchronizationActive()) {
124	            TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
125	                @Override public void afterCommit() { sseHub.publishStock(dishId, available); }
126	            });
127	        } else {
128	            sseHub.publishStock(dishId, available);
129	        }
130	    }
131	}

