2	
3	import com.webox.common.Api;
4	import com.webox.common.ApiException;
5	import org.slf4j.Logger;
6	import org.slf4j.LoggerFactory;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.scheduling.annotation.Scheduled;
9	import org.springframework.stereotype.Service;
10	
11	import java.time.Duration;
12	import java.time.LocalDate;
13	import java.time.LocalDateTime;
14	import java.time.LocalTime;
15	import java.util.ArrayList;
16	import java.util.LinkedHashMap;
17	import java.util.List;
18	import java.util.Map;
19	
20	@Service
21	public class RedisStockService {
22	    private static final Logger log = LoggerFactory.getLogger(RedisStockService.class);
23	    private final RedisClient redis;
24	    private final JdbcTemplate jdbc;
25	
26	    public RedisStockService(RedisClient redis, JdbcTemplate jdbc) {
27	        this.redis = redis;
28	        this.jdbc = jdbc;
29	    }
30	
31	    public static final class Preallocation {
32	        private final List<long[]> entries = new ArrayList<>();
33	        private final LocalDate date;
34	        private boolean degraded;
35	        public Preallocation(LocalDate date) { this.date = date; }
36	        public synchronized void add(long dishId, int qty) { entries.add(new long[]{dishId, qty}); }
37	        public synchronized List<long[]> entries() { return new ArrayList<>(entries); }
38	        public LocalDate date() { return date; }
39	        public boolean isDegraded() { return degraded; }
40	        public void markDegraded() { degraded = true; }
41	    }
42	
43	    private String key(LocalDate date, long dishId) { return "webox:stock:" + date + ":" + dishId; }
44	
45	    private int ttl(LocalDate date) {
46	        long secs = Duration.between(LocalDateTime.now(), date.atTime(LocalTime.of(23, 59, 59))).getSeconds();
47	        return (int) Math.max(60, secs);
48	    }
49	
50	    /**
51	     * Best-effort Redis preallocation. Any Redis failure degrades the whole order to DB_ATOMIC.
52	     * Throws STOCK_INSUFFICIENT when Redis explicitly reports insufficient stock.
53	     */
54	    public void prealloc(Preallocation ctx, long dishId, LocalDate date, int qty, int dbAvailable) {
55	        if (ctx.isDegraded() || !redis.enabled()) { ctx.markDegraded(); return; }
56	        try {
57	            String k = key(date, dishId);
58	            String v = redis.get(k);
59	            if (v == null) {
60	                redis.set(k, String.valueOf(Math.max(0, dbAvailable)), ttl(date));
61	            }
62	            long r = redis.prealloc(k, qty);
63	            if (r == 1) {
64	                ctx.add(dishId, qty);
65	                return;
66	            }
67	            if (r == -1) {
68	                redis.set(k, String.valueOf(Math.max(0, dbAvailable)), ttl(date));
69	                r = redis.prealloc(k, qty);
70	                if (r == 1) { ctx.add(dishId, qty); return; }
71	            }
72	            if (r == 0) {
73	                Map<String, Object> d = new LinkedHashMap<>();
74	                d.put("dishId", dishId);
75	                d.put("requested", qty);
76	                d.put("available", dbAvailable);
77	                Map<String, Object> data = new LinkedHashMap<>();
78	                data.put("details", List.of(d));
79	                throw Api.error(409, "STOCK_INSUFFICIENT", "Some dishes are sold out or insufficient", data);
80	            }
81	        } catch (ApiException e) {
82	            throw e;
83	        } catch (Exception e) {
84	            log.warn("Redis preallocation failed, degrading order to DB_ATOMIC: {}", e.getMessage());
85	            ctx.markDegraded();
86	        }
87	    }
88	
89	    /** G3A-M1: compensate the WHOLE order's preallocated list when T1 rolls back. */
90	    public void compensate(Preallocation ctx) {
91	        if (ctx == null) return;
92	        for (long[] e : ctx.entries()) {
93	            try {
94	                redis.incrBy(key(ctx.date(), e[0]), e[1]);
95	            } catch (Exception ex) {
96	                log.warn("Redis compensation failed for dish {}: {}", e[0], ex.getMessage());
97	            }
98	        }
99	    }
100	
101	    public void sync(LocalDate date, long dishId, int available) {
102	        if (!redis.enabled()) return;
103	        try { redis.set(key(date, dishId), String.valueOf(Math.max(0, available)), ttl(date)); }
104	        catch (Exception e) { log.debug("Redis sync skipped: {}", e.getMessage()); }
105	    }
106	
107	    @Scheduled(fixedDelay = 30000)
108	    public void alignAll() {
109	        if (!redis.enabled()) return;
110	        try {
111	            LocalDate today = LocalDate.now(java.time.ZoneId.of("Asia/Shanghai"));
112	            for (Map<String, Object> r : jdbc.queryForList(
113	                    "SELECT dish_id, serve_date, total_qty-reserved_qty-sold_qty AS available FROM dish_daily_stock "
114	                            + "WHERE inventory_mode='REDIS_PREALLOC' AND serve_date>=?", today)) {
115	                LocalDate d = ((java.sql.Date) r.get("serve_date")).toLocalDate();
116	                sync(d, ((Number) r.get("dish_id")).longValue(),
117	                        Math.max(0, ((Number) r.get("available")).intValue()));
118	            }
119	        } catch (Exception e) {
120	            log.debug("Redis alignment skipped: {}", e.getMessage());
121	        }
122	    }
123	}

1	package com.webox.realtime;
2	
3	import com.webox.common.Util;
4	import org.slf4j.Logger;
5	import org.slf4j.LoggerFactory;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.scheduling.annotation.Scheduled;
8	import org.springframework.stereotype.Component;
9	import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
10	
11	import java.time.LocalDate;
12	import java.util.ArrayList;
13	import java.util.LinkedHashMap;
14	import java.util.List;
15	import java.util.Map;
16	import java.util.concurrent.CopyOnWriteArrayList;
17	
18	@Component
19	public class SseHub {
20	    private static final Logger log = LoggerFactory.getLogger(SseHub.class);
21	    private final List<Entry> emitters = new CopyOnWriteArrayList<>();
22	    private final JdbcTemplate jdbc;
23	
24	    public SseHub(JdbcTemplate jdbc) {
25	        this.jdbc = jdbc;
26	    }
27	
28	    private record Entry(SseEmitter emitter, LocalDate date) {}
29	
30	    public SseEmitter subscribe(LocalDate date) {
31	        SseEmitter emitter = new SseEmitter(0L);
32	        Entry entry = new Entry(emitter, date);
33	        emitter.onCompletion(() -> emitters.remove(entry));
34	        emitter.onTimeout(() -> { emitters.remove(entry); emitter.complete(); });
35	        emitter.onError(e -> emitters.remove(entry));
36	        emitters.add(entry);
37	        try {
38	            emitter.send(SseEmitter.event().reconnectTime(3000L).name("snapshot").data(Util.json(snapshot(date))));
39	        } catch (Exception e) {
40	            emitters.remove(entry);
41	            emitter.completeWithError(e);
42	        }
43	        log.info("SSE subscriber added, active={}", emitters.size());
44	        return emitter;
45	    }
46	
47	    public List<Map<String, Object>> snapshot(LocalDate date) {
48	        List<Map<String, Object>> rows = jdbc.queryForList(
49	                "SELECT s.dish_id, s.total_qty-s.reserved_qty-s.sold_qty AS available FROM dish_daily_stock s "
50	                        + "JOIN daily_menu m ON m.dish_id=s.dish_id AND m.serve_date=s.serve_date "
51	                        + "JOIN dishes d ON d.id=s.dish_id AND d.status='ON_SHELF' "
52	                        + "WHERE s.serve_date=? AND m.publish_status='PUBLISHED' ORDER BY s.dish_id", date);
53	        List<Map<String, Object>> out = new ArrayList<>();
54	        for (Map<String, Object> r : rows) {
55	            Map<String, Object> m = new LinkedHashMap<>();
56	            m.put("dishId", r.get("dish_id"));
57	            m.put("available", Math.max(0, Util.intVal(r.get("available"))));
58	            out.add(m);
59	        }
60	        return out;
61	    }
62	
63	    public void publishStock(long dishId, int available) {
64	        Map<String, Object> data = new LinkedHashMap<>();
65	        data.put("dishId", dishId);
66	        data.put("available", Math.max(0, available));
67	        for (Entry e : emitters) {
68	            try {
69	                e.emitter().send(SseEmitter.event().reconnectTime(3000L).name("stock").data(Util.json(data)));
70	            } catch (Exception ex) {
71	                emitters.remove(e);
72	                try { e.emitter().complete(); } catch (Exception ignored) {}
73	            }
74	        }
75	    }
76	
77	    @Scheduled(fixedDelay = 15000)
78	    public void heartbeat() {
79	        for (Entry e : emitters) {
80	            try {
81	                e.emitter().send(SseEmitter.event().comment("ping"));
82	            } catch (Exception ex) {
83	                emitters.remove(e);
84	            }
85	        }
86	    }
87	
88	    public int activeConnections() { return emitters.size(); }
89	}

