18	import org.springframework.web.cors.UrlBasedCorsConfigurationSource;
19	
20	import java.util.List;
21	
22	@Configuration
23	public class SecurityConfig {
24	    private final JwtFilter jwtFilter;
25	
26	    public SecurityConfig(JwtFilter jwtFilter) {
27	        this.jwtFilter = jwtFilter;
28	    }
29	
30	    @Bean
31	    public PasswordEncoder passwordEncoder() {
32	        return new BCryptPasswordEncoder(10);
33	    }
34	
35	    @Bean
36	    public SecurityFilterChain filterChain(HttpSecurity http,
37	                                           @Value("${webox.cors.allowed-origin:http://127.0.0.1:5173}") String origin) throws Exception {
38	        http.csrf(csrf -> csrf.disable())
39	                .cors(c -> c.configurationSource(corsSource(origin)))
40	                .sessionManagement(s -> s.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
41	                .authorizeHttpRequests(a -> a
42	                        .requestMatchers("/api/v1/auth/register", "/api/v1/auth/login", "/api/v1/auth/refresh",
43	                                "/api/v1/health", "/api/v1/menu/stream", "/images/**", "/error").permitAll()
44	                        .requestMatchers("/api/v1/admin/**").hasRole("ADMIN")
45	                        .anyRequest().authenticated())
46	                .exceptionHandling(e -> e
47	                        .authenticationEntryPoint((req, res, ex) -> write(res, 401, "AUTH_UNAUTHORIZED", "Authentication required"))
48	                        .accessDeniedHandler((req, res, ex) -> write(res, 403, "FORBIDDEN", "Access denied")))
49	                .addFilterBefore(jwtFilter, UsernamePasswordAuthenticationFilter.class);
50	        return http.build();
51	    }
52	
53	    private void write(HttpServletResponse res, int status, String code, String msg) throws java.io.IOException {
54	        res.setStatus(status);
55	        res.setContentType("application/json;charset=UTF-8");
56	        res.getWriter().write("{\"code\":\"" + code + "\",\"message\":\"" + msg
57	                + "\",\"data\":null,\"requestId\":\"" + com.webox.common.RequestContext.requestId() + "\"}");
58	    }
59	
60	    private CorsConfigurationSource corsSource(String origin) {
61	        CorsConfiguration c = new CorsConfiguration();
62	        c.setAllowedOrigins(List.of(origin, "http://localhost:5173", "http://127.0.0.1:5173"));
63	        c.setAllowedMethods(List.of("GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"));
64	        c.setAllowedHeaders(List.of("Authorization", "Idempotency-Key", "Content-Type", "X-Test-Clock", "Accept"));
65	        c.setExposedHeaders(List.of("X-Request-Id"));
66	        c.setAllowCredentials(true);
67	        c.setMaxAge(3600L);
68	        UrlBasedCorsConfigurationSource s = new UrlBasedCorsConfigurationSource();
69	        s.registerCorsConfiguration("/**", c);
70	        return s;
71	    }
72	
73	    public static UserPrincipal current() {
74	        var auth = org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication();
75	        if (auth == null || !(auth.getPrincipal() instanceof UserPrincipal p)) {
76	            throw Api.error(401, "AUTH_UNAUTHORIZED", "Authentication required");
77	        }
78	        return p;
79	    }
80	}

1	package com.webox.security;
2	
3	import com.webox.common.ApiException;
4	import jakarta.servlet.FilterChain;
5	import jakarta.servlet.ServletException;
6	import jakarta.servlet.http.HttpServletRequest;
7	import jakarta.servlet.http.HttpServletResponse;
8	import org.slf4j.MDC;
9	import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
10	import org.springframework.security.core.authority.SimpleGrantedAuthority;
11	import org.springframework.security.core.context.SecurityContextHolder;
12	import org.springframework.stereotype.Component;
13	import org.springframework.web.filter.OncePerRequestFilter;
14	
15	import java.io.IOException;
16	import java.util.List;
17	
18	@Component
19	public class JwtFilter extends OncePerRequestFilter {
20	    private final JwtService jwtService;
21	
22	    public JwtFilter(JwtService jwtService) {
23	        this.jwtService = jwtService;
24	    }
25	
26	    @Override
27	    protected void doFilterInternal(HttpServletRequest req, HttpServletResponse res, FilterChain chain)
28	            throws ServletException, IOException {
29	        String header = req.getHeader("Authorization");
30	        if (header != null && header.startsWith("Bearer ")) {
31	            try {
32	                UserPrincipal p = jwtService.parse(header.substring(7).trim());
33	                UsernamePasswordAuthenticationToken auth = new UsernamePasswordAuthenticationToken(
34	                        p, null, List.of(new SimpleGrantedAuthority("ROLE_" + p.role())));
35	                SecurityContextHolder.getContext().setAuthentication(auth);
36	                MDC.put("userId", String.valueOf(p.id()));
37	            } catch (ApiException e) {
38	                res.setStatus(401);
39	                res.setContentType("application/json;charset=UTF-8");
40	                res.getWriter().write("{\"code\":\"" + e.getCode() + "\",\"message\":\"" + e.getMessage()
41	                        + "\",\"data\":null,\"requestId\":\"" + MDC.get("requestId") + "\"}");
42	                return;
43	            }
44	        }
45	        try {
46	            chain.doFilter(req, res);
47	        } finally {
48	            MDC.remove("userId");
49	        }
50	    }
51	}

