54	    }
55	
56	    @PostMapping(value = "/recommend", produces = MediaType.TEXT_EVENT_STREAM_VALUE)
57	    public SseEmitter recommend(@RequestBody Dtos.AiReq req) {
58	        UserPrincipal user = SecurityConfig.current();
59	        limiter.check("ai:" + user.id(), 10, 60_000);
60	        String prompt = req.prompt() == null ? "" : req.prompt();
61	        if (prompt.length() > 500) {
62	            throw com.webox.common.Api.error(400, "VALIDATION_INVALID", "prompt must be at most 500 characters");
63	        }
64	        SseEmitter emitter = new SseEmitter(25_000L);
65	        String sessionId = req.sessionId() == null || req.sessionId().isBlank()
66	                ? "s-" + UUID.randomUUID().toString().substring(0, 8) : req.sessionId();
67	        executor.submit(() -> run(emitter, user, prompt, sessionId));
68	        return emitter;
69	    }
70	
71	    private record Candidate(long dishId, String name, String category, String spice, long price, int available,
72	                             String protein, double score) {}
73	
74	    private void run(SseEmitter emitter, UserPrincipal user, String prompt, String sessionId) {
75	        long start = System.currentTimeMillis();
76	        try {
77	            List<Candidate> candidates = candidates(user.id());
78	            List<String> reasons = new ArrayList<>();
79	            List<Candidate> chosen;
80	            boolean fallback = llmKey == null || llmKey.isBlank();
81	            String model = fallback ? "rule-based" : llmModel;
82	            List<Candidate> llmChosen = fallback ? null : tryLlm(prompt, candidates, reasons);
83	            if (llmChosen != null) {
84	                chosen = llmChosen;
85	            } else {
86	                fallback = true;
87	                model = "rule-based";
88	                chosen = candidates.stream().limit(5).toList();
89	                reasons.clear();
90	                for (Candidate c : chosen) reasons.add(reasonFor(c));
91	            }
92	            Map<String, Object> meta = new LinkedHashMap<>();
93	            meta.put("fallback", fallback);
94	            meta.put("model", model);
95	            meta.put("sessionId", sessionId);
96	            emitter.send(SseEmitter.event().reconnectTime(3000L).name("meta").data(Util.json(meta)));
97	            List<Long> ids = new ArrayList<>();
98	            for (int i = 0; i < chosen.size(); i++) {
99	                Candidate c = chosen.get(i);
100	                ids.add(c.dishId());
101	                Map<String, Object> dish = new LinkedHashMap<>();
102	                dish.put("dishId", c.dishId());
103	                dish.put("name", c.name());
104	                dish.put("priceCents", c.price());
105	                dish.put("priceDisplay", Util.money(c.price()));
106	                dish.put("category", c.category());
107	                dish.put("available", c.available());
108	                emitter.send(SseEmitter.event().name("dish").data(Util.json(dish)));
109	                Map<String, Object> reason = new LinkedHashMap<>();
110	                reason.put("dishId", c.dishId());
111	                reason.put("text", i < reasons.size() ? reasons.get(i) : reasonFor(c));
112	                emitter.send(SseEmitter.event().name("reason").data(Util.json(reason)));
113	            }
114	            emitter.send(SseEmitter.event().name("done").data(Util.json(Map.of("dishIds", ids))));
115	            persist(user.id(), sessionId, prompt, ids, model, fallback, System.currentTimeMillis() - start);
116	            emitter.complete();
117	        } catch (Exception e) {
118	            log.warn("AI recommend failed: {}", e.getMessage());
119	            try { emitter.completeWithError(e); } catch (Exception ignored) {}
120	        }
121	    }
122	
123	    private List<Candidate> candidates(long userId) {
124	        List<String> allergens = new ArrayList<>();
125	        List<String> preferred = new ArrayList<>();
126	        String spice = null;
127	        Long budgetMax = null;
128	        List<Map<String, Object>> prefs = jdbc.queryForList("SELECT * FROM user_preferences WHERE user_id=?", userId);
129	        if (!prefs.isEmpty()) {
130	            allergens = Util.parseList((String) prefs.get(0).get("allergens"));
131	            preferred = Util.parseList((String) prefs.get(0).get("preferred_categories"));
132	            spice = (String) prefs.get(0).get("spice_preference");
133	            budgetMax = prefs.get(0).get("budget_max_cents") == null ? null : Util.cents(prefs.get(0).get("budget_max_cents"));
134	        }
135	        Set<Long> recent = new HashSet<>();
136	        for (Map<String, Object> r : jdbc.queryForList(
137	                "SELECT DISTINCT oi.dish_id FROM order_items oi JOIN orders o ON o.id=oi.order_id "
138	                        + "WHERE o.user_id=? AND o.status<>'Cancelled' AND o.created_at>=NOW(3)-INTERVAL 7 DAY", userId)) {
139	            recent.add(((Number) r.get("dish_id")).longValue());
140	        }
141	        List<Map<String, Object>> weightsRows = jdbc.queryForList(
142	                "SELECT config_json FROM ai_rule_config WHERE config_key='recommend_weights' AND active=1 ORDER BY version DESC LIMIT 1");
143	        Map<String, Object> w = weightsRows.isEmpty()
144	                ? Util.parseMap("{\"preferredCategory\":3,\"spiceMatch\":2,\"budgetFit\":2,\"protein\":1,\"taste\":1}")
145	                : Util.parseMap(String.valueOf(weightsRows.get(0).get("config_json")));
146	
147	        List<Candidate> out = new ArrayList<>();
148	        for (Map<String, Object> r : jdbc.queryForList(
149	                "SELECT d.id,d.name,d.category,d.spice_level,d.price_cents,d.allergens,d.protein,"
150	                        + "s.total_qty-s.reserved_qty-s.sold_qty AS available FROM dishes d "
151	                        + "JOIN daily_menu m ON m.dish_id=d.id AND m.serve_date=? AND m.publish_status='PUBLISHED' "
152	                        + "JOIN dish_daily_stock s ON s.dish_id=d.id AND s.serve_date=m.serve_date "
153	                        + "WHERE d.status='ON_SHELF'", RequestContext.today())) {
154	            long id = ((Number) r.get("id")).longValue();
155	            if (recent.contains(id)) continue;
156	            int avail = Math.max(0, Util.intVal(r.get("available")));
157	            if (avail <= 0) continue;
158	            List<String> dishAllergens = Util.parseList((String) r.get("allergens"));
159	            if (dishAllergens.stream().anyMatch(allergens::contains)) continue;
160	            String category = String.valueOf(r.get("category"));
161	            long price = Util.cents(r.get("price_cents"));
162	            double score = 0;
163	            if (preferred.contains(category)) score += num(w.get("preferredCategory"), 3);
164	            if (spice != null && spice.equals(String.valueOf(r.get("spice_level")))) score += num(w.get("spiceMatch"), 2);
165	            if (budgetMax == null || price <= budgetMax) score += num(w.get("budgetFit"), 2);
166	            if (r.get("protein") != null) score += num(w.get("protein"), 1);
167	            out.add(new Candidate(id, String.valueOf(r.get("name")), category,
168	                    String.valueOf(r.get("spice_level")), price, avail,
169	                    String.valueOf(r.get("protein")), score));
170	        }
171	        out.sort(Comparator.comparingDouble(Candidate::score).reversed().thenComparing(Candidate::name));
172	        return out;
173	    }
174	
175	    private double num(Object o, double def) {
176	        return o instanceof Number n ? n.doubleValue() : def;
177	    }
178	
179	    private String reasonFor(Candidate c) {
180	        String text = "Matches your preferences: " + c.category() + ", " + c.spice() + " spice, ready today.";
181	        return text.length() > 200 ? text.substring(0, 200) : text;
182	    }
183	
184	    /** Optional OpenAI-compatible call; any failure falls back to rules. */
185	    private List<Candidate> tryLlm(String prompt, List<Candidate> candidates, List<String> reasons) {
186	        if (candidates.isEmpty()) return null;
187	        try {
188	            StringBuilder list = new StringBuilder();
189	            for (Candidate c : candidates) {
190	                list.append(c.dishId()).append(": ").append(c.name()).append(" (").append(c.category())
191	                        .append(", ¥").append(c.price() / 100).append(".").append(String.format("%02d", c.price() % 100)).append(")\n");
192	            }
193	            String userMsg = "User request: " + prompt + "\nCandidate dishes (id: name):\n" + list
194	                    + "\nReturn ONLY a JSON array like [{\"dishId\":1,\"reason\":\"...\"}] using only candidate ids.";
195	            Map<String, Object> body = new LinkedHashMap<>();
196	            body.put("model", llmModel);
197	            body.put("temperature", 0.3);
198	            body.put("max_tokens", 500);
199	            body.put("messages", List.of(
200	                    Map.of("role", "system", "content", "You are a meal recommendation assistant. Only choose from the supplied candidate ids."),
201	                    Map.of("role", "user", "content", userMsg)));
202	            HttpClient client = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).build();
203	            HttpRequest request = HttpRequest.newBuilder(URI.create(llmBase.replaceAll("/$", "") + "/chat/completions"))
204	                    .timeout(Duration.ofSeconds(8))
205	                    .header("Authorization", "Bearer " + llmKey)
206	                    .header("Content-Type", "application/json")
207	                    .POST(HttpRequest.BodyPublishers.ofString(Util.json(body)))
208	                    .build();
209	            HttpResponse<String> resp = client.send(request, HttpResponse.BodyHandlers.ofString());
210	            if (resp.statusCode() / 100 != 2) return null;
211	            Map<String, Object> root = Util.parseMap(resp.body());
212	            List<Map<String, Object>> choices = (List<Map<String, Object>>) root.get("choices");
213	            if (choices == null || choices.isEmpty()) return null;
214	            Map<String, Object> msg = (Map<String, Object>) choices.get(0).get("message");
215	            String content = String.valueOf(msg.get("content"));
216	            String json = content.substring(content.indexOf('['), content.lastIndexOf(']') + 1);
217	            List<Map<String, Object>> parsed = Util.parseListOfMaps(json);
218	            Map<Long, Candidate> byId = new LinkedHashMap<>();
219	            for (Candidate c : candidates) byId.put(c.dishId(), c);
220	            List<Candidate> chosen = new ArrayList<>();
221	            for (Map<String, Object> p : parsed) {
222	                long id = Util.cents(p.get("dishId"));
223	                Candidate c = byId.get(id);
224	                if (c != null && !chosen.contains(c)) {
225	                    chosen.add(c);
226	                    String reason = String.valueOf(p.get("reason"));
227	                    reasons.add(reason.length() > 200 ? reason.substring(0, 200) : reason);
228	                }
229	            }
230	            return chosen.isEmpty() ? null : chosen.stream().limit(5).toList();
231	        } catch (Exception e) {
232	            log.warn("LLM call failed, falling back to rules: {}", e.getMessage());
233	            return null;
234	        }
235	    }
236	
237	    private void persist(long userId, String sessionId, String prompt, List<Long> ids, String model,
238	                         boolean fallback, long latencyMs) {
239	        try {
240	            Map<String, Object> resp = new LinkedHashMap<>();
241	            resp.put("dishIds", ids);
242	            jdbc.update("INSERT INTO ai_conversation(user_id,session_id,prompt,response_json,dish_ids,model,fallback,latency_ms) "
243	                            + "VALUES (?,?,?,?,?,?,?,?)",
244	                    userId, sessionId, prompt, Util.json(resp), Util.json(ids), model, fallback ? 1 : 0, (int) latencyMs);
245	        } catch (Exception e) {
246	            log.debug("AI conversation persist skipped: {}", e.getMessage());
247	        }
248	    }
