75	            if (!needle.isEmpty() && !name.toLowerCase().contains(needle) && !description.toLowerCase().contains(needle)) continue;
76	            int qty = available.getOrDefault(((Number) d.get("id")).longValue(), 0);
77	            boolean forYou = recommend && (preferredCats.contains(category)
78	                    || (spicePref != null && spicePref.equals(String.valueOf(d.get("spice_level")))));
79	            Map<String, Object> m = new LinkedHashMap<>();
80	            long dishId = ((Number) d.get("id")).longValue();
