181	    /**
182	     * Normalize a JDBC datetime value to LocalDateTime.
183	     * MySQL Connector/J returns DATETIME columns as LocalDateTime, but drivers/column
184	     * types and test doubles may return java.sql.Timestamp, OffsetDateTime, Date or a
185	     * String instead. Never cast blindly; unknown/null values yield null (caller decides).
186	     */
187	    public static LocalDateTime localDateTime(Object o) {
188	        if (o == null) return null;
189	        if (o instanceof LocalDateTime ldt) return ldt;
190	        if (o instanceof java.sql.Timestamp ts) return ts.toLocalDateTime();
191	        if (o instanceof java.time.OffsetDateTime odt) return odt.atZoneSameInstant(RequestContext.ZONE).toLocalDateTime();
192	        if (o instanceof ZonedDateTime zdt) return zdt.withZoneSameInstant(RequestContext.ZONE).toLocalDateTime();
193	        if (o instanceof java.time.Instant inst) return LocalDateTime.ofInstant(inst, RequestContext.ZONE);
194	        if (o instanceof java.util.Date d) return LocalDateTime.ofInstant(d.toInstant(), RequestContext.ZONE);
195	        String s = String.valueOf(o).trim();
196	        if (s.isEmpty()) return null;
197	        int space = s.indexOf(' ');
198	        String iso = space > 0 ? s.substring(0, space) + 'T' + s.substring(space + 1) : s;
199	        try { return LocalDateTime.parse(iso); } catch (Exception ignored) { /* fall through */ }
200	        try { return LocalDateTime.of(java.time.LocalDate.parse(s), LocalTime.MIDNIGHT); } catch (Exception ignored) { /* fall through */ }
201	        try { return java.time.OffsetDateTime.parse(iso).atZoneSameInstant(RequestContext.ZONE).toLocalDateTime(); } catch (Exception ignored) { /* fall through */ }
202	        return null;
203	    }
204	}

