3	import org.springframework.stereotype.Component;
4	
5	import java.security.SecureRandom;
6	import java.util.Base64;
7	import java.util.Map;
8	import java.util.concurrent.ConcurrentHashMap;
9	
10	@Component
11	public class TicketStore {
12	    private static final SecureRandom RANDOM = new SecureRandom();
13	    private final Map<String, Ticket> tickets = new ConcurrentHashMap<>();
14	
15	    private static final class Ticket {
16	        final long userId;
17	        final String ip;
18	        final long expiresAt;
19	        final int[] uses = {0};
20	        Ticket(long userId, String ip, long expiresAt) { this.userId = userId; this.ip = ip; this.expiresAt = expiresAt; }
21	    }
22	
23	    public String issue(long userId, String ip) {
24	        byte[] r = new byte[32];
25	        RANDOM.nextBytes(r);
26	        String t = Base64.getUrlEncoder().withoutPadding().encodeToString(r);
27	        tickets.put(t, new Ticket(userId, ip, System.currentTimeMillis() + 60_000));
28	        tickets.entrySet().removeIf(e -> e.getValue().expiresAt < System.currentTimeMillis());
29	        return t;
30	    }
31	
32	    /** Returns userId or -1 when the ticket is invalid/expired/over-used. */
33	    public long redeem(String ticket, String ip) {
34	        Ticket t = tickets.get(ticket);
35	        if (t == null) return -1;
36	        synchronized (t) {
37	            if (t.expiresAt < System.currentTimeMillis()) { tickets.remove(ticket); return -1; }
38	            if (t.ip != null && ip != null && !t.ip.equals(ip)) return -1;
39	            if (t.uses[0] >= 3) { tickets.remove(ticket); return -1; }
40	            t.uses[0]++;
41	            return t.userId;
42	        }
43	    }
44	}

