39	    // ---------------- dishes ----------------
40	    public Map<String, Object> listDishes(int page, int size, String search, String category, String status) {
41	        Util.validatePage(page, size);
42	        if (category != null && !category.isBlank() && !Util.CATEGORIES.contains(category)) {
43	            throw Api.error(400, "VALIDATION_CATEGORY", "Invalid category");
44	        }
45	        if (status != null && !status.isBlank() && !List.of("ON_SHELF", "OFF_SHELF").contains(status)) {
46	            throw Api.error(400, "VALIDATION_INVALID", "Invalid status");
47	        }
48	        if (search != null && search.length() > 50) throw Api.error(400, "VALIDATION_SEARCH_LENGTH", "Search too long");
49	        StringBuilder where = new StringBuilder(" WHERE 1=1");
50	        List<Object> args = new ArrayList<>();
51	        if (search != null && !search.isBlank()) {
52	            where.append(" AND (name LIKE ? ESCAPE '\\\\' OR description LIKE ? ESCAPE '\\\\')");
53	            String p = "%" + Util.escapeLike(search.trim()) + "%";
54	            args.add(p);
55	            args.add(p);
56	        }
57	        if (category != null && !category.isBlank()) { where.append(" AND category=?"); args.add(category); }
58	        if (status != null && !status.isBlank()) { where.append(" AND status=?"); args.add(status); }
59	        Long total = jdbc.queryForObject("SELECT COUNT(*) FROM dishes" + where, Long.class, args.toArray());
60	        args.add(size);
61	        args.add((page - 1) * size);
62	        List<Map<String, Object>> rows = jdbc.queryForList(
63	                "SELECT id,name,description,price_cents,category,protein,allergens,spice_level,image_url,status FROM dishes"
64	                        + where + " ORDER BY id LIMIT ? OFFSET ?", args.toArray());
65	        List<Map<String, Object>> items = new ArrayList<>();
66	        for (Map<String, Object> r : rows) items.add(dishView(r));
67	        Map<String, Object> data = new LinkedHashMap<>();
68	        data.put("items", items);
69	        data.put("page", page);
70	        data.put("size", size);
71	        data.put("total", total == null ? 0 : total);
72	        return data;
73	    }
