80	        m.put("priceCents", Util.cents(r.get("price_cents")));
81	        m.put("category", r.get("category"));
82	        m.put("protein", r.get("protein"));
83	        m.put("allergens", Util.parseList((String) r.get("allergens")));
84	        m.put("spiceLevel", r.get("spice_level"));
85	        m.put("imageUrl", r.get("image_url"));
86	        m.put("status", r.get("status"));
