90	    @Transactional
91	    public Map<String, Object> createDish(Dtos.DishReq req) {
92	        validateDish(req);
93	        jdbc.update("INSERT INTO dishes(name,description,price_cents,category,protein,allergens,spice_level,image_url,status) "
94	                        + "VALUES (?,?,?,?,?,?,?,?,'ON_SHELF')",
95	                req.name().trim(), req.description().trim(), req.priceCents(), req.category(), req.protein(),
96	                Util.json(req.allergens() == null ? List.of() : req.allergens()), req.spiceLevel(), req.imageUrl());
97	        Long id = jdbc.queryForObject("SELECT LAST_INSERT_ID()", Long.class);
98	        Map<String, Object> after = jdbc.queryForMap("SELECT * FROM dishes WHERE id=?", id);
99	        audit.log("DISH_CREATE", "DISH", String.valueOf(id), null, after, null);
100	        menuService.invalidate();
101	        Map<String, Object> data = new LinkedHashMap<>();
102	        data.put("dishId", id);
103	        return data;
104	    }
