106	    @Transactional
107	    public Map<String, Object> updateDish(long dishId, Dtos.DishReq req) {
108	        Map<String, Object> before = jdbc.queryForMap("SELECT * FROM dishes WHERE id=?", dishId);
109	        validateDish(req);
110	        requireReason(req.reason());
111	        jdbc.update("UPDATE dishes SET name=?,description=?,price_cents=?,category=?,protein=?,allergens=?,spice_level=?,image_url=? "
112	                        + "WHERE id=?",
113	                req.name().trim(), req.description().trim(), req.priceCents(), req.category(), req.protein(),
114	                Util.json(req.allergens() == null ? List.of() : req.allergens()), req.spiceLevel(), req.imageUrl(), dishId);
115	        Map<String, Object> after = jdbc.queryForMap("SELECT * FROM dishes WHERE id=?", dishId);
116	        audit.log("DISH_UPDATE", "DISH", String.valueOf(dishId), before, after, req.reason());
117	        menuService.invalidate();
118	        return dishView(after);
119	    }
