124	            throw Api.error(400, "VALIDATION_INVALID", "Invalid status");
125	        }
126	        requireReason(req.reason());
127	        Map<String, Object> before = jdbc.queryForMap("SELECT * FROM dishes WHERE id=?", dishId);
128	        jdbc.update("UPDATE dishes SET status=? WHERE id=?", req.status(), dishId);
129	        Map<String, Object> after = jdbc.queryForMap("SELECT * FROM dishes WHERE id=?", dishId);
130	        audit.log("DISH_STATUS", "DISH", String.valueOf(dishId), before, after, req.reason());
131	        menuService.invalidate();
132	        Map<String, Object> data = new LinkedHashMap<>();
133	        data.put("dishId", dishId);
134	        data.put("status", req.status());
135	        return data;
