138	    public Map<String, Object> uploadImage(long dishId, MultipartFile file) {
139	        jdbc.queryForObject("SELECT id FROM dishes WHERE id=?", Long.class, dishId);
140	        if (file == null || file.isEmpty()) throw Api.error(400, "VALIDATION_IMAGE", "Image file is required");
141	        if (file.getSize() > 5 * 1024 * 1024) throw Api.error(400, "VALIDATION_IMAGE", "Image must be at most 5MB");
142	        try {
143	            byte[] bytes = file.getBytes();
144	            String ext = magicExt(bytes);
145	            if (ext == null) throw Api.error(400, "VALIDATION_IMAGE", "Only jpg, png or webp images are allowed");
146	            Path dir = Paths.get("./uploads/images");
147	            Files.createDirectories(dir);
148	            String name = UUID.randomUUID() + "." + ext;
149	            Files.write(dir.resolve(name), bytes);
150	            String url = "/images/" + name;
151	            jdbc.update("UPDATE dishes SET image_url=? WHERE id=?", url, dishId);
152	            audit.log("DISH_IMAGE", "DISH", String.valueOf(dishId), null, Map.of("imageUrl", url), null);
153	            menuService.invalidate();
154	            Map<String, Object> data = new LinkedHashMap<>();
155	            data.put("imageUrl", url);
156	            return data;
