212	                        + "LEFT JOIN dish_daily_stock s ON s.dish_id=m.dish_id AND s.serve_date=m.serve_date "
213	                        + "WHERE m.serve_date=? ORDER BY m.dish_id", date);
214	        List<Map<String, Object>> out = new ArrayList<>();
215	        for (Map<String, Object> r : rows) {
216	            int total = Util.intVal(r.get("total_qty"));
217	            int reserved = Util.intVal(r.get("reserved_qty"));
218	            int sold = Util.intVal(r.get("sold_qty"));
219	            int available = Math.max(0, total - reserved - sold);
220	            Map<String, Object> m = new LinkedHashMap<>();
221	            m.put("dishId", r.get("dish_id"));
222	            m.put("dishName", r.get("name"));
223	            m.put("totalQty", total);
224	            m.put("reservedQty", reserved);
225	            m.put("soldQty", sold);
226	            m.put("available", available);
227	            m.put("lowStock", available <= 3);
228	            m.put("inventoryMode", r.get("inventory_mode") == null ? "DB_ATOMIC" : r.get("inventory_mode"));
229	            m.put("published", "PUBLISHED".equals(r.get("publish_status")));
