235	    @Transactional
236	    public Map<String, Object> saveDailyMenu(Dtos.DailyMenuReq req) {
237	        if (req.serveDate() == null || req.serveDate().isBlank()) {
238	            throw Api.error(400, "VALIDATION_INVALID", "serveDate is required");
239	        }
240	        LocalDate date = Util.parseDate(req.serveDate(), "VALIDATION_INVALID");
241	        if (req.items() == null || req.items().isEmpty()) {
242	            throw Api.error(400, "VALIDATION_INVALID", "items are required");
243	        }
244	        requireReason(req.reason());
245	        List<Map<String, Object>> before = dailyMenu(date.toString());
246	        for (Dtos.DailyMenuItem item : req.items()) {
247	            if (item.dishId() == null) throw Api.error(400, "VALIDATION_INVALID", "dishId is required");
248	            jdbc.queryForObject("SELECT id FROM dishes WHERE id=?", Long.class, item.dishId());
249	            int total = item.totalQty() == null ? (req.totalQty() == null ? 0 : req.totalQty()) : item.totalQty();
250	            if (total < 0) throw Api.error(400, "VALIDATION_INVALID", "totalQty must be >= 0");
251	            String publish = Boolean.FALSE.equals(item.published()) ? "DRAFT" : "PUBLISHED";
252	            jdbc.update("INSERT INTO daily_menu(dish_id,serve_date,publish_status) VALUES (?,?,?) "
253	                            + "ON DUPLICATE KEY UPDATE publish_status=VALUES(publish_status)",
254	                    item.dishId(), date, publish);
255	            String mode = item.inventoryMode() == null ? "DB_ATOMIC" : item.inventoryMode();
256	            if (!List.of("DB_ATOMIC", "REDIS_PREALLOC").contains(mode)) {
257	                throw Api.error(400, "VALIDATION_INVALID", "Invalid inventoryMode");
258	            }
259	            List<Map<String, Object>> stock = jdbc.queryForList(
260	                    "SELECT reserved_qty+sold_qty AS used FROM dish_daily_stock WHERE dish_id=? AND serve_date=?",
261	                    item.dishId(), date);
262	            if (stock.isEmpty()) {
263	                jdbc.update("INSERT INTO dish_daily_stock(dish_id,serve_date,total_qty,inventory_mode) VALUES (?,?,?,?)",
264	                        item.dishId(), date, total, mode);
265	            } else {
266	                int used = Util.intVal(stock.get(0).get("used"));
267	                if (total < used) throw Api.error(409, "STOCK_INSUFFICIENT", "totalQty cannot be lower than reserved + sold");
268	                jdbc.update("UPDATE dish_daily_stock SET total_qty=?, inventory_mode=?, version=version+1 "
269	                        + "WHERE dish_id=? AND serve_date=?", total, mode, item.dishId(), date);
270	            }
271	        }
272	        List<Map<String, Object>> after = dailyMenu(date.toString());
273	        audit.log("DAILY_MENU_UPDATE", "DAILY_MENU", date.toString(), before, after, req.reason());
274	        menuService.invalidate();
275	        Map<String, Object> data = new LinkedHashMap<>();
276	        data.put("serveDate", date.toString());
277	        data.put("items", after);
278	        return data;
279	    }
