282	    public Map<String, Object> updateStock(String serveDate, long dishId, Dtos.StockReq req) {
283	        requireReason(req.reason());
284	        if (req.totalQty() == null || req.totalQty() < 0) {
285	            throw Api.error(400, "VALIDATION_INVALID", "totalQty must be >= 0");
