289	                "SELECT total_qty, reserved_qty, sold_qty FROM dish_daily_stock WHERE dish_id=? AND serve_date=?", dishId, date);
290	        int n = jdbc.update("UPDATE dish_daily_stock SET total_qty=?, version=version+1 "
291	                        + "WHERE dish_id=? AND serve_date=? AND ?>=reserved_qty+sold_qty",
292	                req.totalQty(), dishId, date, req.totalQty());
293	        if (n == 0) throw Api.error(409, "STOCK_INSUFFICIENT", "totalQty cannot be lower than reserved + sold");
