295	        Map<String, Object> after = Map.of("totalQty", req.totalQty(), "available", available);
296	        audit.log("STOCK_UPDATE", "STOCK", dishId + ":" + date, before, after, req.reason());
297	        menuService.invalidate();
298	        Map<String, Object> data = new LinkedHashMap<>();
299	        data.put("dishId", dishId);
300	        data.put("serveDate", date.toString());
301	        data.put("totalQty", req.totalQty());
302	        data.put("available", available);
303	        return data;
304	    }
