306	    public Map<String, Object> reconcile(String dateStr) {
307	        LocalDate date = dateStr == null || dateStr.isBlank() ? RequestContext.today()
308	                : Util.parseDate(dateStr, "VALIDATION_INVALID");
309	        List<Map<String, Object>> drift = new ArrayList<>();
310	        List<Map<String, Object>> rows = jdbc.queryForList(
311	                "SELECT s.dish_id, s.total_qty, s.total_qty-s.reserved_qty-s.sold_qty AS book_available, "
312	                        + "s.total_qty - COALESCE(SUM(CASE l.entry_type WHEN 'RESERVE' THEN l.qty WHEN 'RELEASE' THEN -l.qty ELSE 0 END),0) AS ledger_derived "
313	                        + "FROM dish_daily_stock s LEFT JOIN inventory_ledger l "
314	                        + "ON l.dish_id=s.dish_id AND l.serve_date=s.serve_date "
315	                        + "WHERE s.serve_date=? GROUP BY s.dish_id,s.total_qty,s.reserved_qty,s.sold_qty", date);
316	        for (Map<String, Object> r : rows) {
317	            long book = Util.cents(r.get("book_available"));
318	            long derived = Util.cents(r.get("ledger_derived"));
319	            if (book != derived) {
320	                Map<String, Object> d = new LinkedHashMap<>();
321	                d.put("dishId", r.get("dish_id"));
322	                d.put("bookAvailable", book);
323	                d.put("ledgerDerived", derived);
324	                drift.add(d);
325	            }
326	        }
327	        Map<String, Object> data = new LinkedHashMap<>();
328	        data.put("date", date.toString());
329	        data.put("checked", rows.size());
330	        data.put("drift", drift);
331	        return data;
332	    }
