524	    public Map<String, Object> putAiRules(Dtos.AiRuleReq req) {
525	        requireReason(req.reason());
526	        String configKey = req.configKey() == null || req.configKey().isBlank() ? "recommend_weights" : req.configKey();
527	        String configJson;
528	        if (req.rollbackToVersion() != null) {
529	            List<Map<String, Object>> hist = jdbc.queryForList(
530	                    "SELECT config_json FROM ai_rule_config WHERE config_key=? AND version=?", configKey, req.rollbackToVersion());
531	            if (hist.isEmpty()) throw Api.error(400, "VALIDATION_INVALID", "Rollback version not found");
532	            configJson = String.valueOf(hist.get(0).get("config_json"));
533	        } else {
534	            if (req.config() == null || req.config().isNull()) {
535	                throw Api.error(400, "VALIDATION_INVALID", "config is required");
536	            }
537	            configJson = req.config().toString();
538	        }
539	        Integer maxVersion = jdbc.queryForObject(
540	                "SELECT COALESCE(MAX(version),0) FROM ai_rule_config WHERE config_key=?", Integer.class, configKey);
541	        int version = (maxVersion == null ? 0 : maxVersion) + 1;
542	        jdbc.update("UPDATE ai_rule_config SET active=0 WHERE config_key=?", configKey);
543	        jdbc.update("INSERT INTO ai_rule_config(config_key,version,config_json,active,change_reason,created_by) VALUES (?,?,?,1,?,?)",
544	                configKey, version, configJson, req.reason(), com.webox.config.SecurityConfig.current().id());
545	        audit.log("AI_RULE_UPDATE", "AI_RULE", configKey + ":v" + version, null,
546	                Map.of("version", version, "rollbackToVersion", req.rollbackToVersion()), req.reason());
547	        return getAiRules();
548	    }
