1	package com.webox.inventory;
2	
3	import org.springframework.beans.factory.annotation.Value;
4	import org.springframework.stereotype.Component;
5	
6	import java.io.BufferedInputStream;
7	import java.io.BufferedOutputStream;
8	import java.io.InputStream;
9	import java.io.OutputStream;
10	import java.net.InetSocketAddress;
11	import java.net.Socket;
12	import java.nio.charset.StandardCharsets;
13	
14	/**
15	 * Minimal RESP (Redis protocol) client. Kept dependency-free so that Redis remains optional
16	 * and any connectivity failure can be handled as a graceful degradation by callers.
17	 */
18	@Component
19	public class RedisClient {
20	    private final boolean enabled;
21	    private final String host;
22	    private final int port;
23	    private final int timeoutMs;
24	
25	    public RedisClient(@Value("${webox.redis.enabled:true}") boolean enabled,
26	                       @Value("${webox.redis.host:127.0.0.1}") String host,
27	                       @Value("${webox.redis.port:6379}") int port,
28	                       @Value("${webox.redis.timeout-ms:300}") int timeoutMs) {
29	        this.enabled = enabled;
30	        this.host = host;
31	        this.port = port;
32	        this.timeoutMs = timeoutMs;
33	    }
34	
35	    public boolean enabled() { return enabled; }
36	
37	    public boolean ping() {
38	        if (!enabled) return false;
39	        try {
40	            Object r = command("PING");
41	            return "PONG".equals(String.valueOf(r));
42	        } catch (Exception e) {
43	            return false;
44	        }
45	    }
46	
47	    public String get(String key) {
48	        Object r = command("GET", key);
49	        return r == null ? null : String.valueOf(r);
50	    }
51	
52	    public void set(String key, String value, int ttlSeconds) {
53	        command("SET", key, value, "EX", String.valueOf(ttlSeconds));
54	    }
55	
56	    public long decrBy(String key, long n) {
57	        Object r = command("DECRBY", key, String.valueOf(n));
58	        return ((Number) r).longValue();
59	    }
60	
61	    public long incrBy(String key, long n) {
62	        Object r = command("INCRBY", key, String.valueOf(n));
63	        return ((Number) r).longValue();
64	    }
65	
66	    /** Lua preallocation: returns 1 ok, 0 insufficient, -1 key missing. */
67	    public long prealloc(String key, long qty) {
68	        String lua = "local v=tonumber(redis.call('GET',KEYS[1]) or '-1') "
69	                + "if v<0 then return -1 end "
70	                + "if v<tonumber(ARGV[1]) then return 0 end "
71	                + "redis.call('DECRBY',KEYS[1],ARGV[1]) return 1";
72	        Object r = command("EVAL", lua, "1", key, String.valueOf(qty));
73	        return ((Number) r).longValue();
74	    }
75	
76	    public Object command(String... args) {
77	        if (!enabled) throw new IllegalStateException("redis disabled");
78	        try (Socket socket = new Socket()) {
79	            socket.connect(new InetSocketAddress(host, port), timeoutMs);
80	            socket.setSoTimeout(timeoutMs);
81	            OutputStream out = new BufferedOutputStream(socket.getOutputStream());
82	            StringBuilder sb = new StringBuilder("*").append(args.length).append("\r\n");
83	            for (String a : args) {
84	                byte[] b = a.getBytes(StandardCharsets.UTF_8);
85	                sb.append("$").append(b.length).append("\r\n").append(a).append("\r\n");
86	            }
87	            out.write(sb.toString().getBytes(StandardCharsets.UTF_8));
88	            out.flush();
89	            InputStream in = new BufferedInputStream(socket.getInputStream());
90	            return read(in);
91	        } catch (Exception e) {
92	            throw new IllegalStateException("redis command failed: " + e.getMessage(), e);
93	        }
94	    }
95	
96	    private Object read(InputStream in) throws Exception {
97	        int type = in.read();
98	        if (type < 0) throw new IllegalStateException("empty redis response");
99	        String line = readLine(in);
100	        switch (type) {
101	            case '+': return line;
102	            case '-': throw new IllegalStateException("redis error: " + line);
103	            case ':': return Long.parseLong(line);
104	            case '$': {
105	                int len = Integer.parseInt(line);
106	                if (len < 0) return null;
107	                byte[] buf = in.readNBytes(len);
108	                readLine(in);
109	                return new String(buf, StandardCharsets.UTF_8);
110	            }
111	            case '*': {
112	                int n = Integer.parseInt(line);
113	                if (n < 0) return null;
114	                Object[] arr = new Object[n];
115	                for (int i = 0; i < n; i++) arr[i] = read(in);
116	                return arr;
117	            }
118	            default: throw new IllegalStateException("unknown redis reply type " + type);
119	        }
120	    }
121	
122	    private String readLine(InputStream in) throws Exception {
123	        StringBuilder sb = new StringBuilder();
124	        int c;
125	        while ((c = in.read()) != -1) {
126	            if (c == '\r') {
127	                int n = in.read();
128	                if (n == '\n') break;
129	                sb.append((char) c).append((char) n);
130	            } else {
131	                sb.append((char) c);
132	            }
133	        }
134	        return sb.toString();
135	    }
136	}

